     1|/**
     2| * CanonicalInvestmentReelCard — the ONE shared reel card for IVX.
     3| *
     4| * Used by:
     5| *   • Main/Home feed (mode="feed")
     6| *   • Reels module (mode="reel")
     7| *   • Landing page (mode="feed")
     8| *
     9| * Visual design (owner-approved):
    10| *   Full-bleed vertical media (video or image)
    11| *   Investment + Active badges (top-left)
    12| *   Property title + location (bottom-left, over gradient)
    13| *   ROI / Min Investment / Min Ownership metrics
    14| *   Tokenized / JV Deal / Buyer category options
    15| *   Right-side action rail: Like, Comment, Save, Share, Audio
    16| *   View Deal + Invest Now CTAs (bottom)
    17| *
    18| * Data sources:
    19| *   Accepts a unified `CanonicalReelData` props object that can be
    20| *   mapped from FeedVideo, HomeFeedDeal, PublishedDealCardModel, or
    21| *   ParsedJVDeal — all via the adapter functions in this file.
    22| */
    23|import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
    24|import {
    25|  View,
    26|  Text,
    27|  StyleSheet,
    28|  TouchableOpacity,
    29|  Share,
    30|  Alert,
    31|  AppState,
    32|  Platform,
    33|  useWindowDimensions,
    34|  type ViewStyle,
    35|} from 'react-native';
    36|import { ResizeMode } from 'expo-av';
    37|import { LinearGradient } from 'expo-linear-gradient';
    38|import { Image } from 'expo-image';
    39|import { useSafeAreaInsets } from 'react-native-safe-area-context';
    40|import * as Haptics from 'expo-haptics';
    41|import {
    42|  Heart,
    43|  MessageCircle,
    44|  Share2,
    45|  Bookmark,
    46|  Volume2,
    47|  VolumeX,
    48|  Play,
    49|  Hexagon,
    50|  Users,
    51|  Home,
    52|} from 'lucide-react-native';
    53|import Colors from '@/constants/colors';
    54|import SafeVideo from '@/components/SafeVideo';
    55|import ReelVideoPlayer from '@/components/ReelVideoPlayer';
    56|import { formatCount, compactCurrency } from '@/lib/reel-formatters';
    57|import { toggleProjectLike, trackProjectShare } from '@/lib/project-engagement';
    58|import { toggleVideoSave, getViewerId, buildVideoShareUrl } from '@/lib/video-platform';
    59|
    60|// ─── Types ─────────────────────────────────────────────────────────────
    61|
    62|export type ReelMode = 'reel' | 'feed';
    63|export type ReelMediaType = 'video' | 'image';
    64|
    65|export interface CanonicalReelData {
    66|  /** Unique identifier for this reel item (video ID or deal ID). */
    67|  reelId: string;
    68|  /** Linked JV deal ID (used for View Deal / Invest Now navigation). */
    69|  dealId: string | null;
    70|  /** Property ID if different from dealId. */
    71|  propertyId: string | null;
    72|  /** Investment ID if different from dealId. */
    73|  investmentId: string | null;
    74|  /** URL slug for deep linking. */
    75|  slug: string | null;
    76|  /** Display title (property name or video title). */
    77|  title: string;
    78|  /** Subtitle / tour label. */
    79|  subtitle: string;
    80|  /** Location string (city, state). */
    81|  location: string | null;
    82|  /** Primary media URL (video or image). */
    83|  mediaUrl: string | null;
    84|  /** Media type — video or image. */
    85|  mediaType: ReelMediaType;
    86|  /** HLS adaptive stream URL (preferred for video). */
    87|  hlsUrl: string | null;
    88|  /** Poster/thumbnail URL for video. */
    89|  posterUrl: string | null;
    90|  /** Blurred placeholder URL for instant first paint. */
    91|  previewBlurUrl: string | null;
    92|  /** Expected ROI percentage. */
    93|  roi: number | null;
    94|  /** Minimum investment amount in dollars. */
    95|  minimumInvestment: number | null;
    96|  /** Minimum ownership percentage. */
    97|  minimumOwnership: string | null;
    98|  /** Deal status (published, active, etc.). */
    99|  status: string;
   100|  /** Deal category (jv, development, etc.). */
   101|  category: string | null;
   102|  /** Like count. */
   103|  likeCount: number;
   104|  /** Comment count. */
   105|  commentCount: number;
   106|  /** Save count. */
   107|  saveCount: number;
   108|  /** Share count. */
   109|  shareCount: number;
   110|  /** Whether the current user has liked this reel. */
   111|  isLiked: boolean;
   112|  /** Whether the current user has saved this reel. */
   113|  isSaved: boolean;
   114|  /** Whether audio is enabled (video only). */
   115|  audioEnabled: boolean;
   116|  /** Creator ID for follow tracking. */
   117|  creatorId: string | null;
   118|  /** Full deal URL for deep-link navigation. */
   119|  dealUrl: string | null;
   120|}
   121|
   122|export interface CanonicalInvestmentReelCardProps {
   123|  data: CanonicalReelData;
   124|  mode: ReelMode;
   125|  /** Whether this card is the active/visible item (reel mode only). */
   126|  isActive: boolean;
   127|  /** Whether to mount the video player (reel mode — active ± 1 only). */
   128|  shouldMountVideo: boolean;
   129|  /** Whether audio is muted globally (reel mode). */
   130|  isMuted: boolean;
   131|  /** Card height for feed mode (default: 520). */
   132|  feedHeight: number;
   133|  /** Callbacks. */
   134|  onOpenDeal: (data: CanonicalReelData) => void;
   135|  onInvest: (data: CanonicalReelData) => void;
   136|  onLike: (data: CanonicalReelData) => void;
   137|  onComment: (data: CanonicalReelData) => void;
   138|  onSave: (data: CanonicalReelData) => void;
   139|  onShare: (data: CanonicalReelData) => void;
   140|  onToggleMute: () => void;
   141|  /** Test ID prefix. */
   142|  testIDPrefix?: string;
   143|}
   144|
   145|// ─── Investment options ────────────────────────────────────────────────
   146|
   147|interface InvestmentOption {
   148|  id: string;
   149|  label: string;
   150|  icon: React.ReactNode;
   151|  tint: string;
   152|}
   153|
   154|function useInvestmentOptions(dealType: string | null | undefined): InvestmentOption[] {
   155|  const t = (dealType ?? '').toLowerCase();
   156|  const tokenized: InvestmentOption = {
   157|    id: 'tokenized',
   158|    label: 'Tokenized',
   159|    icon: <Hexagon size={16} color={Colors.primary} />,
   160|    tint: Colors.primary,
   161|  };
   162|  const jvDeals: InvestmentOption = {
   163|    id: 'jvDeals',
   164|    label: 'JV Deal',
   165|    icon: <Users size={16} color={Colors.blue} />,
   166|    tint: Colors.blue,
   167|  };
   168|  const buyers: InvestmentOption = {
   169|    id: 'buyers',
   170|    label: 'Buyer',
   171|    icon: <Home size={16} color={Colors.green} />,
   172|    tint: Colors.green,
   173|  };
   174|  switch (t) {
   175|    case 'jv':
   176|    case 'equity_split':
   177|    case 'hybrid':
   178|      return [tokenized, jvDeals, buyers];
   179|    case 'development':
   180|    case 'new_construction':
   181|    case 'rehab_construction':
   182|      return [jvDeals, tokenized, buyers];
   183|    case 'profit_sharing':
   184|      return [tokenized, buyers, jvDeals];
   185|    default:
   186|      return [tokenized, jvDeals, buyers];
   187|  }
   188|}
   189|
   190|// ─── Component ─────────────────────────────────────────────────────────
   191|
   192|const CanonicalInvestmentReelCard = memo(function CanonicalInvestmentReelCard({
   193|  data,
   194|  mode,
   195|  isActive,
   196|  shouldMountVideo,
   197|  isMuted,
   198|  feedHeight = 520,
   199|  onOpenDeal,
   200|  onInvest,
   201|  onLike,
   202|  onComment,
   203|  onSave,
   204|  onShare,
   205|  onToggleMute,
   206|  testIDPrefix = 'reel-card',
   207|}: CanonicalInvestmentReelCardProps) {
   208|  const insets = useSafeAreaInsets();
   209|  const { height: screenHeight } = useWindowDimensions();
   210|  const [paused, setPaused] = useState<boolean>(false);
   211|  const [showHeart, setShowHeart] = useState<boolean>(false);
   212|  const [progress, setProgress] = useState<number>(0);
   213|  const [liked, setLiked] = useState<boolean>(data.isLiked);
   214|  const [likeCount, setLikeCount] = useState<number>(data.likeCount);
   215|  const [saved, setSaved] = useState<boolean>(data.isSaved);
   216|  const [saveCount, setSaveCount] = useState<number>(data.saveCount);
   217|  const [viewerId, setViewerId] = useState<string | null>(null);
   218|  const [appState, setAppState] = useState<string>('active');
   219|  const [isInViewport, setIsInViewport] = useState<boolean>(false);
   220|  const lastTapRef = useRef<number>(0);
   221|  const viewRef = useRef<View>(null);
   222|  // Stable progress handler — avoids creating a new arrow function on
   223|  // every render, which would cause ReelVideoPlayer/SafeVideo to
   224|  // re-render ~10x/second during playback.
   225|  const handleProgress = useCallback((p: number) => {
   226|    setProgress(p);
   227|  }, []);
   228|
   229|  const isReel = mode === 'reel';
   230|  const cardHeight = isReel ? screenHeight : feedHeight;
   231|
   232|  // Fetch viewer ID for engagement tracking
   233|  useEffect(() => {
   234|    let cancelled = false;
   235|    void getViewerId().then((id) => {
   236|      if (!cancelled) setViewerId(id);
   237|    });
   238|    return () => { cancelled = true; };
   239|  }, []);
   240|
   241|  // Pause video when app goes to background
   242|  useEffect(() => {
   243|    const subscription = AppState.addEventListener('change', (nextState: string) => {
   244|      setAppState(nextState);
   245|    });
   246|    return () => subscription.remove();
   247|  }, []);
   248|
   249|  // Viewability detection for feed mode
   250|  useEffect(() => {
   251|    if (isReel) return; // reel mode uses isActive from parent
   252|    const interval = setInterval(() => {
   253|      if (!viewRef.current || appState !== 'active') {
   254|        setIsInViewport(false);
   255|        return;
   256|      }
   257|      viewRef.current.measure((_x, _y, w, h, pageX, pageY) => {
   258|        if (!h || h <= 0) return;
   259|        const visibleTop = Math.max(pageY, 0);
   260|        const visibleBottom = Math.min(pageY + h, screenHeight);
   261|        const visibleHeight = Math.max(0, visibleBottom - visibleTop);
   262|        const visibilityRatio = visibleHeight / h;
   263|        setIsInViewport(visibilityRatio >= 0.6);
   264|      });
   265|    }, 500);
   266|    return () => clearInterval(interval);
   267|  }, [appState, screenHeight, isReel]);
   268|
   269|  const shouldPlay = isReel
   270|    ? isActive && !paused && appState === 'active'
   271|    : isInViewport && appState === 'active' && !paused;
   272|
   273|  const investmentOptions = useInvestmentOptions(data.category);
   274|  const isActiveStatus = (data.status ?? 'published') === 'published';
   275|  const hasDeal = data.dealId !== null;
   276|
   277|  // Sync local state when props change
   278|  useEffect(() => {
   279|    setLiked(data.isLiked);
   280|    setLikeCount(data.likeCount);
   281|  }, [data.isLiked, data.likeCount]);
   282|
   283|  useEffect(() => {
   284|    setSaved(data.isSaved);
   285|    setSaveCount(data.saveCount);
   286|  }, [data.isSaved, data.saveCount]);
   287|
   288|  const handleTap = useCallback(() => {
   289|    if (data.mediaType !== 'video') return;
   290|    const now = Date.now();
   291|    if (now - lastTapRef.current < 320) {
   292|      lastTapRef.current = 0;
   293|      setShowHeart(true);
   294|      setTimeout(() => setShowHeart(false), 800);
   295|      handleDoubleTapLike();
   296|    } else {
   297|      lastTapRef.current = now;
   298|      setTimeout(() => {
   299|        if (lastTapRef.current === now) {
   300|          setPaused((p) => !p);
   301|        }
   302|      }, 330);
   303|    }
   304|  }, []);
   305|
   306|  const handleDoubleTapLike = useCallback(() => {
   307|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   308|    if (!liked) {
   309|      setLiked(true);
   310|      setLikeCount((prev) => prev + 1);
   311|    }
   312|    onLike(data);
   313|  }, [liked, onLike, data]);
   314|
   315|  const handleLikePress = useCallback(() => {
   316|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   317|    const nextLiked = !liked;
   318|    setLiked(nextLiked);
   319|    setLikeCount((prev) => prev + (nextLiked ? 1 : -1));
   320|    onLike(data);
   321|  }, [liked, onLike, data]);
   322|
   323|  const handleSavePress = useCallback(() => {
   324|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   325|    const nextSaved = !saved;
   326|    setSaved(nextSaved);
   327|    setSaveCount((prev) => prev + (nextSaved ? 1 : -1));
   328|    onSave(data);
   329|  }, [saved, onSave, data]);
   330|
   331|  const handleSharePress = useCallback(() => {
   332|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   333|    onShare(data);
   334|  }, [onShare, data]);
   335|
   336|  const handleCommentPress = useCallback(() => {
   337|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   338|    onComment(data);
   339|  }, [onComment, data]);
   340|
   341|  const handleViewDeal = useCallback(() => {
   342|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   343|    onOpenDeal(data);
   344|  }, [onOpenDeal, data]);
   345|
   346|  const handleInvestNow = useCallback(() => {
   347|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
   348|    onInvest(data);
   349|  }, [onInvest, data]);
   350|
   351|  // Rail position: account for safe area in reel mode, fixed offset in feed mode
   352|  const railBottom = isReel ? insets.bottom + 96 : 96;
   353|  const infoBottom = isReel ? insets.bottom + 26 : 26;
   354|
   355|  const renderMedia = () => {
   356|    if (data.mediaType === 'video' && data.mediaUrl) {
   357|      if (isReel) {
   358|        // Reel mode: use ReelVideoPlayer with mount/unmount lifecycle
   359|        if (shouldMountVideo) {
   360|          return (
   361|            <ReelVideoPlayer
   362|              videoId={data.reelId}
   363|              uri={data.mediaUrl}
   364|              hlsUri={data.hlsUrl}
   365|              posterUri={data.posterUrl}
   366|              previewBlurUri={data.previewBlurUrl}
   367|              shouldPlay={shouldPlay}
   368|              isMuted={isMuted}
   369|              onProgress={handleProgress}
   370|              testID={`${testIDPrefix}-player-${data.reelId}`}
   371|            />
   372|          );
   373|        }
   374|        // Unmounted: show poster to preserve scroll position
   375|        return (
   376|          <View style={StyleSheet.absoluteFill}>
   377|            {data.posterUrl ? (
   378|              <Image
   379|                source={{ uri: data.posterUrl }}
   380|                style={StyleSheet.absoluteFill}
   381|                contentFit="cover"
   382|                transition={150}
   383|              />
   384|            ) : data.previewBlurUrl ? (
   385|              <Image
   386|                source={{ uri: data.previewBlurUrl }}
   387|                style={StyleSheet.absoluteFill}
   388|                contentFit="cover"
   389|                blurRadius={20}
   390|                transition={100}
   391|              />
   392|            ) : (
   393|              <View style={[StyleSheet.absoluteFill, { backgroundColor: '#111' }]} />
   394|            )}
   395|          </View>
   396|        );
   397|      }
   398|      // Feed mode: use SafeVideo with viewability-based playback
   399|      return (
   400|        <SafeVideo
   401|          uri={data.mediaUrl}
   402|          posterUri={data.posterUrl ?? undefined}
   403|          style={StyleSheet.absoluteFill}
   404|          resizeMode={ResizeMode.COVER}
   405|          shouldPlay={shouldPlay}
   406|          isMuted={isMuted}
   407|          isLooping
   408|          testID={`${testIDPrefix}-video-${data.reelId}`}
   409|        />
   410|      );
   411|    }
   412|    // Image media
   413|    if (data.mediaUrl) {
   414|      return (
   415|        <Image
   416|          source={{ uri: data.mediaUrl }}
   417|          style={StyleSheet.absoluteFill}
   418|          contentFit="cover"
   419|          transition={200}
   420|        />
   421|      );
   422|    }
   423|    // Fallback: dark background
   424|    return <View style={[StyleSheet.absoluteFill, { backgroundColor: '#111' }]} />;
   425|  };
   426|
   427|  return (
   428|    <View
   429|      ref={viewRef}
   430|      style={[styles.container, { height: cardHeight }]}
   431|      testID={`${testIDPrefix}-${data.reelId}`}
   432|    >
   433|      {/* Full-bleed media */}
   434|      <TouchableOpacity
   435|        style={StyleSheet.absoluteFill}
   436|        activeOpacity={1}
   437|        onPress={handleTap}
   438|        testID={`${testIDPrefix}-touch-${data.reelId}`}
   439|      >
   440|        {renderMedia()}
   441|      </TouchableOpacity>
   442|
   443|      {/* Progress bar (video only) */}
   444|      {data.mediaType === 'video' && (
   445|        <View style={styles.progressBar}>
   446|          <View style={[styles.progressFill, { width: `${progress * 100}%` }]} />
   447|        </View>
   448|      )}
   449|
   450|      {/* Center play button when paused (video only) */}
   451|      {!shouldPlay && data.mediaType === 'video' && (
   452|        <View pointerEvents="none" style={styles.centerPlay}>
   453|          <View style={styles.centerPlayCircle}>
   454|            <Play size={30} color="#000" fill="#000" />
   455|          </View>
   456|        </View>
   457|      )}
   458|
   459|      {/* Double-tap heart burst */}
   460|      {showHeart && (
   461|        <View pointerEvents="none" style={styles.burstHeart}>
   462|          <Heart size={96} color={Colors.error} fill={Colors.error} />
   463|        </View>
   464|      )}
   465|
   466|      {/* Right action rail — Instagram-style outline icons with counts */}
   467|      <View style={[styles.rail, { bottom: railBottom }]}>
   468|        <TouchableOpacity
   469|          style={styles.railBtn}
   470|          onPress={handleLikePress}
   471|          testID={`${testIDPrefix}-like-${data.reelId}`}
   472|          activeOpacity={0.8}
   473|        >
   474|          <View style={styles.railIconCircle}>
   475|            <Heart
   476|              size={isReel ? 28 : 24}
   477|              color={liked ? Colors.error : '#fff'}
   478|              strokeWidth={1.5}
   479|            />
   480|          </View>
   481|          <Text style={styles.railCount}>{formatCount(likeCount)}</Text>
   482|        </TouchableOpacity>
   483|
   484|        <TouchableOpacity
   485|          style={styles.railBtn}
   486|          onPress={handleCommentPress}
   487|          testID={`${testIDPrefix}-comment-${data.reelId}`}
   488|          activeOpacity={0.8}
   489|        >
   490|          <View style={styles.railIconCircle}>
   491|            <MessageCircle size={isReel ? 28 : 24} color="#fff" strokeWidth={1.5} />
   492|          </View>
   493|          <Text style={styles.railCount}>{formatCount(data.commentCount)}</Text>
   494|        </TouchableOpacity>
   495|
   496|        <TouchableOpacity
   497|          style={styles.railBtn}
   498|          onPress={handleSavePress}
   499|          testID={`${testIDPrefix}-save-${data.reelId}`}
   500|          activeOpacity={0.8}
   501|        >
   502|          <View style={styles.railIconCircle}>
   503|            <Bookmark
   504|              size={isReel ? 28 : 24}
   505|              color={saved ? Colors.primary : '#fff'}
   506|              strokeWidth={1.5}
   507|            />
   508|          </View>
   509|          <Text style={styles.railCount}>{formatCount(saveCount)}</Text>
   510|        </TouchableOpacity>
   511|
   512|        <TouchableOpacity
   513|          style={styles.railBtn}
   514|          onPress={handleSharePress}
   515|          testID={`${testIDPrefix}-share-${data.reelId}`}
   516|          activeOpacity={0.8}
   517|        >
   518|          <View style={styles.railIconCircle}>
   519|            <Share2 size={isReel ? 28 : 24} color="#fff" strokeWidth={1.5} />
   520|          </View>
   521|          <Text style={styles.railCount}>{formatCount(data.shareCount)}</Text>
   522|        </TouchableOpacity>
   523|
   524|        {data.mediaType === 'video' && (
   525|          <TouchableOpacity
   526|            style={styles.railBtn}
   527|            onPress={onToggleMute}
   528|            testID={`${testIDPrefix}-mute-${data.reelId}`}
   529|            activeOpacity={0.8}
   530|          >
   531|            <View style={styles.railIconCircle}>
   532|              {isMuted ? <VolumeX size={24} color="#fff" strokeWidth={1.5} /> : <Volume2 size={24} color="#fff" strokeWidth={1.5} />}
   533|            </View>
   534|          </TouchableOpacity>
   535|        )}
   536|      </View>
   537|
   538|      {/* Full-bleed transparent bottom scrim — Instagram style, no boxy card */}
   539|      <LinearGradient
   540|        pointerEvents="none"
   541|        colors={['transparent', 'rgba(0,0,0,0.35)', 'rgba(0,0,0,0.72)']}
   542|        locations={[0, 0.45, 1]}
   543|        style={styles.bottomScrim}
   544|      />
   545|
   546|      {/* Bottom info + CTAs — fully transparent background over the scrim */}
   547|      <View pointerEvents="box-none" style={[styles.info, { bottom: infoBottom }]}>
   548|        {/* Badges */}
   549|        <View style={styles.badgeRow}>
   550|          {hasDeal && <Text style={styles.badgeInvestment}>INVESTMENT</Text>}
   551|          {isActiveStatus && <Text style={styles.badgeActive}>ACTIVE</Text>}
   552|        </View>
   553|
   554|        {/* Title */}
   555|        <Text style={styles.infoTitle} numberOfLines={1}>
   556|          {data.title}
   557|        </Text>
   558|        {data.subtitle ? (
   559|          <Text style={styles.infoSubtitle} numberOfLines={1}>
   560|            {data.subtitle}
   561|          </Text>
   562|        ) : null}
   563|        {data.location ? (
   564|          <Text style={styles.infoLocation} numberOfLines={1}>
   565|            {data.location}
   566|          </Text>
   567|        ) : null}
   568|
   569|        {/* Metrics */}
   570|        <View style={styles.metricRow}>
   571|          {data.roi != null && data.roi > 0 ? (
   572|            <View style={styles.metric}>
   573|              <Text style={styles.metricValue}>{data.roi}%</Text>
   574|              <Text style={styles.metricLabel}>TARGET ROI</Text>
   575|            </View>
   576|          ) : null}
   577|          {data.minimumInvestment != null && data.minimumInvestment > 0 ? (
   578|            <View style={styles.metric}>
   579|              <Text style={styles.metricValue}>{compactCurrency(data.minimumInvestment)}</Text>
   580|              <Text style={styles.metricLabel}>MIN INVEST</Text>
